L8_1.m_Talk_VTN = L9_1
L9_1 = "\239\188\136\230\136\145\230\132\159\232\167\137\233\162\134\230\130\159\228\186\134\231\156\159\231\136\177\229\146\140\231\137\186\231\137\178\239\188\140\232\191\152\230\156\137\228\186\186\231\148\159\231\154\132\230\132\143\228\185\137\239\188\140\229\133\132\229\188\159\227\128\130\239\188\137"
